import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>圆角和圆形裁剪都能让照片变柔和，但两者不是一回事。一个保留矩形、只把四个角变圆；另一个直接把图片变成圆形。</p>\n<p>这个区别对头像、卡片和社交资料很重要。形状决定了照片怎么放、看着怎么样，选错了可能裁掉人脸，或者和界面格格不入。</p>\n<p>这篇文章会把两种形状直接对比：各自是怎么做的、看着有什么不同、分别适合哪里，以及什么时候组合使用效果最好。对比完可以直接动手：<a href=\"/zh/yuanjiao-tupian/\">图片圆角工具</a>里既能调圆角半径，也能一键裁成圆形。</p>\n<h2 id=\"what-each-shape-does\">两种形状分别是怎么做出来的</h2>\n<p>圆角是把图片保留成矩形，只把四个角沿着弧线切掉。直边还在，只是尖角变成了平滑的曲线。</p>\n<p>圆形裁剪是把图片切成圆形。圆圈之外的部分全部去掉，照片变成一个圆盘，一条直边都不剩。</p>\n<p>圆角是温和的变化。照片看着还是矩形，圆角只是柔化，不是变形。</p>\n<p>圆形裁剪是彻底的变化。照片变成了完全不同的形状，构图一开始就要围着圆边来安排。</p>\n<h2 id=\"how-they-look\">两种形状并排看着有什么不同</h2>\n<p>圆角照片看着现代又友好。适合卡片、缩略图和 App 界面，柔和的边缘和周围的设计是一个风格。</p>\n<p>圆形照片看着像头像或者徽章。视线会被引到正中间，所以适合一眼就要认出来的人脸和 Logo。</p>\n<p>照片就想当一张照片看，选圆角更好。图片保留了矩形的样子，圆角只是一种轻微的修饰。</p>\n<p>照片要表达的是“这是谁”，选圆形更好。圆形本身就在告诉别人，这是一个人或者一个品牌，而不只是一张图。</p>\n<h2 id=\"avatars\">头像：大多数时候圆形赢</h2>\n<p>大多数平台的头像都是圆形的，所以圆形裁剪是最自然的选择。方形照片传上去当头像，平台会自己把它裁成圆，经常裁得很糟。</p>\n<p>先裁成正方形，再用整圆快捷按钮。这样得到的圆形头像人脸居中，没有重要内容被切掉。</p>\n<p>方形头像的平台上，圆角也能用。柔和的圆角方形看着很现代，尖角方形却像没处理过的原文件。</p>\n<p>不管哪种形状，人脸都要留在画面中间。两种形状都会切掉边缘，脸太靠边的话，耳朵或者一部分头发会被裁掉。</p>\n<h2 id=\"cards-and-ui\">卡片和界面：圆角赢</h2>\n<p>卡片本身就是带圆角的矩形，卡片里的照片也应该一样。圆角半径和卡片一致的照片，嵌进去天衣无缝。</p>\n<p>圆形照片放在矩形卡片里看着很别扭。圆形和卡片边缘互相打架，整个版式都失衡了。</p>\n<p>博客卡片只圆上面两个角，下面两个留直角。照片在卡片顶部，直角底部正好和下面的文字对齐。</p>\n<p>同一组卡片的半径要统一。一排圆角一致的卡片看着很专业，半径各不相同就显得杂乱。</p>\n<h2 id=\"social-profiles\">社交资料：先看平台要求</h2>\n<p>每个平台的头像形状都不一样。大多数用圆形，有的用圆角方形，少数还用尖角方形，修图之前先确认平台要求。</p>\n<p>圆形头像的平台，直接上传圆形裁剪好的图。平台会原样显示，不会再动手裁剪，就不会有意外。</p>\n<p>圆角方形头像的平台，上传带轻微圆角的方形图。平台自己可能还会再加圆角，半径小一点，结果更可控。</p>\n<p>一张照片要给好几个平台用，就从同一张原图各做一份：一份圆形，一份方形。每个平台拿到它想要的形状。</p>\n<h2 id=\"product-photos\">商品图：形状和信任感</h2>\n<p>商品图适合圆角，不适合圆形。商品放进圆形里，边缘就没了，看着像徽章而不像商品列表。</p>\n<p>10 到 20 像素的轻微圆角就够了。商品完整可见，卡片又有了现代感。</p>\n<p>整个店铺的半径要统一。圆角一致的店铺看着整齐、可信，形状各不相同就显得很随意。</p>\n<p>促销徽章或者打折标签可以用圆形。圆形的折扣徽章在商品页上很显眼，促销要的就是这个效果。</p>\n<h2 id=\"screenshots\">截图：只能用圆角</h2>\n<p>截图千万别裁成圆形。圆形会去掉屏幕的四个角，而菜单、按钮和状态栏恰恰都在角落里。</p>\n<p>截图用 10 到 20 像素的小半径。轻轻柔化一下，就有了现代卡片的感觉，还不会遮住任何内容。</p>\n<p>圆角截图导出成 PNG。无损格式能让小字保持清晰，截图里是设置项或者报错信息时，这一点很重要。</p>\n<p>同一篇教程里的截图，半径要统一。圆角一致，读者跟着步骤走更顺；半径各不相同，反而分散注意力。</p>\n<h2 id=\"transparency-needs\">透明底：两种形状都需要</h2>\n<p>两种形状都会切掉图片的一部分，空出来的地方要么透明，要么填上纯色。这个选择对两者同样重要。</p>\n<p>网页配图、头像和叠加图层适合透明角。图片能融入任何背景，因为被切掉的地方显示的是图片后面的东西。</p>\n<p>目的地不支持透明时用纯色填充。白色填充让图片看着像一张圆角照片贴在白卡上。</p>\n<p>导出成 PNG 或 WebP 才能保住透明。JPG 没有透明通道，两种形状导出成 JPG 都会被填成纯色，放在彩色背景上很难看。</p>\n<h2 id=\"radius-vs-full-circle\">半径和整圆：是一条线，不是二选一</h2>\n<p>半径和圆形是同一条线上的两个点。小半径是轻微柔化，大半径是强烈的弧线，整圆是这条线的尽头。</p>\n<p>把半径想成一个旋钮，而不是开关。方形到圆形之间任何数值都能选，具体用哪个，看用途和设计。</p>\n<p>大多数照片用小到中等半径最合适。既柔和了图片，又不改变它的样子，几乎放进任何界面都合适。</p>\n<p>头像就直接做到底，做成圆形。半圆不圆的头像看着很犹豫，完整的圆形才是明确、自信的形状。</p>\n<h2 id=\"when-to-use-each\">什么时候用哪种形状</h2>\n<p>头像、个人资料图和徽章用圆形。圆形代表身份，也是平台和观众对人脸、Logo的期待。</p>\n<p>卡片、缩略图、截图和商品图用圆角。矩形保住了完整内容，柔化又让它看着很现代。</p>\n<p>横幅、按钮和标签用胶囊形。两端完全圆润的长条看着像个控件，很适合可交互的元素。</p>\n<p>证件、正式照片和打印品用直角。干净的边缘和内容本身很搭，加圆角反而显得不合时宜。</p>\n<h2 id=\"combining-both\">两种形状一起用</h2>\n<p>不用所有地方都只用一种形状。个人资料可以用圆形头像配圆角帖子图，两种形状互相衬托，效果很好。</p>\n<p>人用圆形，内容用圆角。这个区分能让观众一眼分清，哪个是身份、哪个是帖子。</p>\n<p>每种类型内部要保持一致。所有头像都是圆形，所有卡片共用同一个半径，设计才显得是刻意的。</p>\n<p>别在同一个元素上又圆又切。既圆角又圆形的照片是个混乱的形状，看着像做错了。</p>\n<h2 id=\"platform-rules\">各平台的要求：每个网站想要什么形状</h2>\n<p>社交平台会把头像裁成圆形，所以上传之前自己先裁成圆。方形图传进圆形头像框，平台会替你裁，经常裁得很糟。</p>\n<p>博客和电商平台一般用带圆角的矩形图。轻微圆角和卡片设计很搭，圆形放在这里会显得格格不入。</p>\n<p>聊天软件在聊天列表里把头像显示成圆形，在资料页里显示成大图。圆形裁剪两种场景都适用，因为形状是一样的。</p>\n<p>修图之前花两分钟查一下平台的尺寸指南。确认要求再动手，能避免平台替你重新裁剪。</p>\n<h2 id=\"common-mistakes\">形状选择最常见的几个错误</h2>\n<p>最常见的错误，是方形照片直接传进圆形头像框。平台自己裁剪，人脸经常偏到一边，或者被裁掉一部分。</p>\n<p>另一个错误，是长方形照片直接做圆形裁剪。出来的其实是胶囊形，不是圆形，放不进头像框，看着也不对。</p>\n<p>还有人忘了两种形状都需要透明底。圆形导出成 JPG 会被填成白色，放在深色资料背景上就是一个白色方块。</p>\n<p>最后，别把需要四个角的照片裁成圆形。风景、证件、合影一旦切成圆盘，必要的内容就没了。</p>\n<h2 id=\"print\">打印品里的形状</h2>\n<p>打印照片很少用圆形或者圆角，因为把纸裁成弧线是额外工序。圆形的数字图印在长方形纸上，会显示成纯色填充。</p>\n<p>贴纸和标签正好相反，圆形和圆角就是卖点。圆形贴纸、圆角标签撕贴干净、成品感十足。</p>\n<p>打印圆角图时，填充色要和纸张颜色一致。白纸配白色填充，看着就像一张圆角照片；透明导出再转成 JPG，角落同样会被填成白色。</p>\n<p>徽章和纽扣就用圆形裁剪。圆形的设计和实物本身严丝合缝，图片正好填满。</p>\n<h2 id=\"choosing-cheat-sheet\">选形状速查表</h2>\n<p>头像、个人资料图和徽章用圆形。先裁成正方形，再用整圆快捷按钮，导出成 PNG 或 WebP。</p>\n<p>卡片、缩略图、截图和商品图用圆角。小到中等半径就能柔化图片，又不改变它的样子。</p>\n<p>横幅、按钮和标签用胶囊形。两端完全圆润的长条看着像个控件，很适合可交互的元素。</p>\n<p>证件、正式照片和打印品用直角。干净的边缘和内容本身很搭，加圆角反而显得不合时宜。</p>\n<h2 id=\"shapes-for-messaging\">聊天软件里的形状</h2>\n<p>聊天软件在聊天列表里把头像显示成圆形，在资料页里显示成大图。圆形裁剪两种场景都适用，因为形状在任何尺寸下都一样。</p>\n<p>聊天里分享的照片，App 自己会显示成圆角。直接上传尖角照片就行，App 会替你加圆角，没必要自己先做一遍。</p>\n<p>群头像的标准做法也是圆形裁剪。圆形在很小的尺寸下依然清晰可辨，矩形图会被 App 裁得不可预测。</p>\n<p>聊天头像的人脸要居中，留在画面中间。脸太靠边的话，圆形裁剪会裁掉耳朵或者一部分头发。</p>\n<h2 id=\"shapes-for-email\">邮件签名和通讯里的形状</h2>\n<p>邮件签名里常放一张小头像，圆形裁剪是最专业的选择。圆形照片看着亲切又现代，方形照片却像一份文件。</p>\n<p>签名里头像别太大，100 像素宽左右就好。照片太大会喧宾夺主，小圆形既添了个人感，又不抢正文的风头。</p>\n<p>通讯头部用圆角更合适。轻微圆角和现代邮件模板很搭，尖角却像没处理过的原文件。</p>\n<p>邮件图片的格式看透明需求定。圆形头像需要 PNG 或 WebP 才能通透，白底邮件上的圆角照片用 JPG 也完全够用。</p>\n<p>想看分步操作，请读<a href=\"/zh/blog/zenme-gei-tupian-yuanjiao/\">怎么给图片加圆角</a>，完整指南请读<a href=\"/zh/blog/tupian-yuanjiao-zhinan/\">图片圆角完全指南：半径、透明底与导出格式全讲清</a>。想给圆角照片加边框，可以试试<a href=\"/zh/tupian-biankuang-shengcheng/\">图片边框生成器</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"头像用圆形还是圆角方形好？","answer":"圆形最稳妥，因为大多数平台的头像都是圆形的。先裁成正方形，再用整圆快捷按钮，导出成 PNG 或 WebP。只有在平台显示方形头像时，圆角方形才合适。"},{"question":"商品图能不能用圆形裁剪？","answer":"一般不行。圆形会切掉商品的边角，商品列表看着像徽章而不像店铺商品。用 10 到 20 像素的轻微圆角代替，既柔和了照片，又不会遮住任何商品。"},{"question":"方形照片传进圆形头像框会怎么样？","answer":"平台会自己把它裁成圆形，构图经常很糟：人脸可能偏到一边，或者被裁掉一部分。自己先裁成正方形、做好圆形再上传，才能完全掌控保留下来的部分。"},{"question":"博客卡片用圆角还是圆形好？","answer":"圆角，因为卡片本身就是矩形。只圆上面两个角、下面两个留直角，照片就能稳稳地嵌在文字上方。圆形放进矩形卡片里，和卡片边缘互相打架，看着很失衡。"},{"question":"圆形头像和圆角帖子图能一起用吗？","answer":"可以，而且效果很好。人用圆形，内容用圆角，每种类型内部保持一致。这个区分能让观众一眼分清，哪个是身份、哪个是帖子。"},{"question":"圆形裁剪会让文件变小很多吗？","answer":"只会小一点。圆形去掉了四个角的像素，文件比原来的方形图略小。真正影响文件大小的是导出格式：PNG 比 JPG 大，WebP 则能在保持透明的同时把文件做得很小。"}];
